SELECT CAST(COUNT(DISTINCT CASE WHEN p.drug_type = 'Insulin' THEN e.emr_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT CASE WHEN p.drug_type = 'Oral' THEN e.emr_id END), 0) AS proportion FROM emar e JOIN prescriptions p ON e.emr_id = p.emr_id JOIN icustays s ON e.subject_id = s.subject_id WHERE s.subject_id = 757071 AND s.hadm_id = 757071 AND s.stay_id = 757071 AND s.intime <= '2020-01-01 12:00:00' AND s.outtime >= '2020-12-31 23:59:59' AND (s.outtime - s.intime) >= 48 AND (s.outtime - s.intime) <= 72 AND p.drug_type IN ('Insulin', 'Oral');